    const session2 = (await tx.execute(sql`SELECT id FROM sesiones WHERE id=${sessionId}::uuid
      AND usuario_id=${userId} AND expira_at>${now.toISOString()}::timestamptz
      AND created_at>${new Date(now.getTime() - 16 * 36e5).toISOString()}::timestamptz FOR SHARE`)).rows[0];
    if (!session2) throw new E11Error("NO_AUTENTICADO", "La sesi\xF3n no est\xE1 vigente.", 401);
