      uuid: input.uuid,
      usuarioId: userId,
      actorId: actor4.usuarioId,
      anterior: prior?.perfil ?? "F",
      posterior: input.perfil,
      revision,
      motivo: input.motivo.trim(),
      creadoEn: e11Runtime().now().toISOString()
