  return {
    salidasEnTransito: {
      conteo: Number(row.enTransitoConteo),
      importe: decimal2(row.enTransitoImporte)
    },
    salidasCanceladas: {
      conteo: Number(row.canceladasConteo),
      importe: decimal2(row.canceladasImporte)
    }
  };
