function where2(ctx, range2 = ctx.range, alias2 = "t") {
  const args = [range2.desde.toISOString(), range2.hasta.toISOString()];
  const parts = [`${accountedDocumentAt(alias2)} >= $1`, `${accountedDocumentAt(alias2)} <= $2`];
  const add2 = (column, data, cast = "int[]") => {
    if (data.length) {
      args.push(data);
      parts.push(`${column}=ANY($${args.length}::${cast})`);
    }
  };
  add2(`${alias2}.ubicacion_id`, ctx.locations?.length ? ctx.locations : ids2(ctx.input.ubicacionIds));
  add2("l.producto_id", ids2(ctx.input.productoIds));
  add2(`${alias2}.usuario_terminal_id`, ids2(ctx.input.usuarioIds));
  add2(`${alias2}.cliente_id`, ids2(ctx.input.clienteIds));
  add2("r.proveedor_id", ids2(ctx.input.proveedorIds));
  add2("p.tela", values(ctx.input.telas), "text[]");
  add2("p.color", values(ctx.input.colores), "text[]");
  add2("p.unidad::text", values(ctx.input.unidades), "text[]");
  const modality = reportModality(ctx.input.modalidad);
  if (modality !== "TODO") {
    args.push(modality === "METRAJE" ? "METREADO" : "NORMAL");
    parts.push(`l.tipo::text=$${args.length}`);
  }
  if (typeof ctx.input.facturado === "boolean") {
    args.push(ctx.input.facturado);
    parts.push(`${alias2}.facturado=$${args.length}`);
  }
  const payments = values(ctx.input.formasPago);
  if (payments.length) {
    args.push(payments);
    parts.push(`EXISTS (SELECT 1 FROM ticket_pagos fp WHERE fp.ticket_id=${alias2}.id AND fp.forma_pago::text=ANY($${args.length}::text[]))`);
  }
  return { text: parts.join(" AND "), values: args };
}
async function loadCancellationRows(ctx) {
  const normal = where2(ctx);
  const [cancelled, cancelledProducts] = await Promise.all([
    pool.query(`SELECT t.id ticket_id,t.folio,t.motivo_cancelacion motivo,t.cancelado_at,
        u.nombre sitio,l.tipo,COALESCE(SUM(l.importe),0)::float importe,COUNT(l.id)::int lineas
      ${joins} WHERE ${normal.text} AND t.estado='CANCELADO'
      GROUP BY t.id,t.folio,t.motivo_cancelacion,t.cancelado_at,u.nombre,l.tipo
      ORDER BY t.created_at DESC`, normal.values),
    pool.query(`SELECT p.sku,p.tela,p.color,l.tipo,p.unidad,COUNT(*)::int lineas,
        COALESCE(SUM(l.cantidad),0)::float cantidad,COALESCE(SUM(l.importe),0)::float importe
      ${joins} WHERE ${normal.text} AND t.estado='CANCELADO'
      GROUP BY p.id,l.tipo,p.unidad ORDER BY importe DESC`, normal.values)
  ]);
  const rows2 = cancelled.rows.map((row) => ({
    ticketId: Number(row.ticket_id),
    folio: String(row.folio),
    modalidad: modalityLabel(row.tipo),
    motivo: row.motivo == null ? null : String(row.motivo),
    sitio: String(row.sitio),
    lineas: number6(row.lineas),
    importe: number6(row.importe),
    canceladoAt: row.cancelado_at == null ? null : new Date(row.cancelado_at).toISOString(),
    documentoHref: `/tickets/${Number(row.ticket_id)}`
  }));
  const products = cancelledProducts.rows.map((row) => ({
    sku: String(row.sku),
    tela: String(row.tela),
    color: String(row.color),
    modalidad: modalityLabel(row.tipo),
    unidad: String(row.unidad),
    lineas: number6(row.lineas),
    cantidad: number6(row.cantidad),
    importe: number6(row.importe)
  }));
  const summary = summarizeCancellationRows(rows2);
  return { summary, rows: rows2, products };
}
